import { describe, expect, test, beforeEach, afterEach } from "vitest";
import {
  verifyReleaseTrain,
  detectDivergence,
  resolveMergeConflict,
  selectOrchestrationRoute,
  validateQAGate,
  checkBuildProof,
  canAutoMerge,
} from "./release-orchestrator";

describe("Release Train Orchestration", () => {
  describe("divergence detection", () => {
    const TEST_CASES = [
      {
        name: "staging ahead of main by 3 commits",
        staging: "fc542eb",
        main: "dd3f0e7",
        expectedDiverged: true,
        expectedDistance: 3,
      },
      {
        name: "no divergence (main == staging)",
        staging: "a82b6ff",
        main: "a82b6ff",
        expectedDiverged: false,
        expectedDistance: 0,
      },
      {
        name: "main ahead of staging",
        staging: "dd3f0e7",
        main: "fc542eb",
        expectedDiverged: true,
        expectedDistance: 3,
      },
      {
        name: "merge commit in history",
        staging: "a82b6ff", // Merge agent/funding-equilibrium
        main: "4aa7873",
        expectedDiverged: true,
        expectedHasMergeCommit: true,
      },
    ];

    TEST_CASES.forEach(({ name, staging, main, expectedDiverged, expectedDistance, expectedHasMergeCommit }) => {
      test(`detect divergence: ${name}`, () => {
        const result = detectDivergence(staging, main);
        expect(result.diverged).toBe(expectedDiverged);
        if (expectedDistance !== undefined) {
          expect(result.distance).toBe(expectedDistance);
        }
        if (expectedHasMergeCommit !== undefined) {
          expect(result.hasMergeCommit).toBe(expectedHasMergeCommit);
        }
      });
    });

    test("rejects invalid commit hashes", () => {
      expect(() => detectDivergence("invalid", "abc123")).toThrow();
      expect(() => detectDivergence("", "abc123")).toThrow();
      expect(() => detectDivergence(null, "abc123")).toThrow();
    });
  });

  describe("release-train proof verification", () => {
    test("verify build proof exists for commit", () => {
      const commit = "a82b6ff";
      const proof = checkBuildProof(commit, "npm run build");
      expect(proof).toEqual(
        expect.objectContaining({
          commit,
          buildCommand: "npm run build",
          verified: expect.any(Boolean),
        })
      );
    });

    test("reject commit without build proof", () => {
      const result = checkBuildProof("fc542eb", "npm run build");
      expect(result.verified).toBe(false);
      expect(result.error).toBeDefined();
    });

    test("require exact commit match for proof", () => {
      const result = checkBuildProof("fc542eb", "npm run build");
      // Proof from fc542eb cannot satisfy requirement for a82b6ff
      expect(result.verified).toBe(false);
    });

    test("invalidate proof if build command differs", () => {
      const result = checkBuildProof("a82b6ff", "npm run test && npm run build");
      expect(result.verified).toBe(false);
    });
  });

  describe("orchestration route selection", () => {
    const ROUTE_TEST_CASES = [
      {
        name: "hard task class routes through full pipeline",
        taskClass: "hard",
        expectedRoute: {
          triage: "google:gemini-2.0-flash",
          planner: "deepseek:deepseek-v4-flash",
          coder: "claude:haiku",
        },
      },
      {
        name: "medium task class uses simplified route",
        taskClass: "medium",
        expectedRoute: {
          triage: null,
          planner: "deepseek:deepseek-v4-flash",
          coder: "claude:haiku",
        },
      },
      {
        name: "easy task class is direct",
        taskClass: "easy",
        expectedRoute: {
          coder: "claude:haiku",
        },
      },
    ];

    ROUTE_TEST_CASES.forEach(({ name, taskClass, expectedRoute }) => {
      test(`route selection: ${name}`, () => {
        const route = selectOrchestrationRoute(taskClass);
        expect(route).toEqual(expect.objectContaining(expectedRoute));
      });
    });

    test("invalid task class rejects", () => {
      expect(() => selectOrchestrationRoute("unknown")).toThrow();
      expect(() => selectOrchestrationRoute("")).toThrow();
    });
  });

  describe("QA gate validation", () => {
    const QA_TEST_CASES = [
      {
        name: "all QA agents pass",
        qaResults: [
          { agent: "local:llama3.1", passed: true, coverage: 0.95 },
          { agent: "local:llama3.2:3b", passed: true, coverage: 0.97 },
          { agent: "deepseek:deepseek-v4-flash", passed: true, coverage: 0.99 },
        ],
        expectedGatePassed: true,
      },
      {
        name: "one QA agent fails",
        qaResults: [
          { agent: "local:llama3.1", passed: true, coverage: 0.95 },
          { agent: "local:llama3.2:3b", passed: false, coverage: 0.45 },
          { agent: "deepseek:deepseek-v4-flash", passed: true, coverage: 0.99 },
        ],
        expectedGatePassed: false,
      },
      {
        name: "coverage below minimum threshold",
        qaResults: [
          { agent: "local:llama3.1", passed: true, coverage: 0.50 },
          { agent: "local:llama3.2:3b", passed: true, coverage: 0.55 },
          { agent: "deepseek:deepseek-v4-flash", passed: true, coverage: 0.60 },
        ],
        expectedGatePassed: false,
        expectedReason: "coverage_below_threshold",
      },
    ];

    QA_TEST_CASES.forEach(({ name, qaResults, expectedGatePassed, expectedReason }) => {
      test(`QA gate: ${name}`, () => {
        const result = validateQAGate(qaResults);
        expect(result.passed).toBe(expectedGatePassed);
        if (expectedReason) {
          expect(result.reason).toBe(expectedReason);
        }
      });
    });

    test("QA gate requires minimum 2 agents", () => {
      const result = validateQAGate([{ agent: "local:llama3.1", passed: true, coverage: 0.95 }]);
      expect(result.passed).toBe(false);
    });
  });

  describe("merge conflict resolution", () => {
    test("resolve merge: cleanup obsolete artifacts", () => {
      const result = resolveMergeConflict({
        message: "cleanup obsolete composables, middleware, config artifacts",
        branches: ["agent/funding-equilibrium"],
        scope: "safe_patch",
      });
      expect(result.strategy).toBe("squash_cleanup");
      expect(result.safeToMerge).toBe(true);
    });

    test("reject merge: feature addition violates scope", () => {
      const result = resolveMergeConflict({
        message: "add new payment processor integration",
        branches: ["feature/new-processor"],
        scope: "safe_patch",
      });
      expect(result.safeToMerge).toBe(false);
      expect(result.reason).toContain("feature addition");
    });

    test("accept merge: bug fix within scope", () => {
      const result = resolveMergeConflict({
        message: "fix: memory leak in event listener cleanup",
        branches: ["bugfix/memory-leak"],
        scope: "safe_patch",
      });
      expect(result.safeToMerge).toBe(true);
      expect(result.strategy).toBeDefined();
    });

    test("flag merge: licensing/transmission implications", () => {
      const result = resolveMergeConflict({
        message: "change dependency licensing from MIT to GPL",
        branches: ["deps/license-update"],
        scope: "safe_patch",
      });
      expect(result.requiresLegalReview).toBe(true);
    });
  });

  describe("auto-merge eligibility", () => {
    test("eligible: passed QA, verified build, cleanup scope", () => {
      const result = canAutoMerge({
        qaGatePassed: true,
        buildVerified: true,
        mergeStrategy: "squash_cleanup",
        scope: "safe_patch",
        requiresLegalReview: false,
      });
      expect(result.eligible).toBe(true);
      expect(result.targetBranch).toBe("orchestrator/dev");
    });

    test("ineligible: build not verified", () => {
      const result = canAutoMerge({
        qaGatePassed: true,
        buildVerified: false,
        mergeStrategy: "squash_cleanup",
        scope: "safe_patch",
        requiresLegalReview: false,
      });
      expect(result.eligible).toBe(false);
    });

    test("ineligible: QA gate failed", () => {
      const result = canAutoMerge({
        qaGatePassed: false,
        buildVerified: true,
        mergeStrategy: "squash_cleanup",
        scope: "safe_patch",
        requiresLegalReview: false,
      });
      expect(result.eligible).toBe(false);
    });

    test("blocked: legal review required", () => {
      const result = canAutoMerge({
        qaGatePassed: true,
        buildVerified: true,
        mergeStrategy: "squash_cleanup",
        scope: "safe_patch",
        requiresLegalReview: true,
      });
      expect(result.eligible).toBe(false);
      expect(result.blockedBy).toBe("legal_gate");
    });
  });

  describe("production push guard", () => {
    test("block push without release-train proof", () => {
      const result = verifyReleaseTrain({
        commit: "a82b6ff",
        targetBranch: "main",
        hasProof: false,
      });
      expect(result.allowed).toBe(false);
      expect(result.error).toContain("green release-train proof");
    });

    test("allow push with valid proof", () => {
      const result = verifyReleaseTrain({
        commit: "a82b6ff",
        targetBranch: "main",
        hasProof: true,
        proof: { verified: true, buildCommand: "npm run build" },
      });
      expect(result.allowed).toBe(true);
    });

    test("suggest orchestrator/dev fallback", () => {
      const result = verifyReleaseTrain({
        commit: "a82b6ff",
        targetBranch: "main",
        hasProof: false,
      });
      expect(result.suggestion).toBe("orchestrator/dev");
    });

    test("emergency override with explicit env var", () => {
      process.env.ORCH_ALLOW_UNVERIFIED_PROD_PUSH = "1";
      const result = verifyReleaseTrain({
        commit: "a82b6ff",
        targetBranch: "main",
        hasProof: false,
      });
      expect(result.allowed).toBe(true);
      expect(result.overridden).toBe(true);
      delete process.env.ORCH_ALLOW_UNVERIFIED_PROD_PUSH;
    });
  });

  describe("end-to-end orchestration flow", () => {
    test("complete pipeline: divergence -> resolve -> verify -> merge -> release", () => {
      const orchestrationFlow = {
        divergenceDetected: true,
        mergeResolved: true,
        qaGatePassed: true,
        buildVerified: true,
        autoMergeEligible: true,
        releaseTrained: true,
      };

      const allPassed = Object.values(orchestrationFlow).every((v) => v === true);
      expect(allPassed).toBe(true);
    });

    test("flow halts at first failure: missing QA gate", () => {
      const orchestrationFlow = {
        divergenceDetected: true,
        mergeResolved: true,
        qaGatePassed: false,
        buildVerified: true,
        autoMergeEligible: false,
      };

      const canProceed = orchestrationFlow.qaGatePassed && orchestrationFlow.buildVerified;
      expect(canProceed).toBe(false);
    });
  });
});
